package qa.domain;
import domain.ability.*;import domain.ability.progression.*;import domain.character.CharacterClass;import domain.character.sheet.CharacterSheet;import domain.economy.*;import domain.inventory.item.*;import domain.inventory.item.misc.AstrolabeItem;import domain.social.*;import java.util.*;
public final class CanonicalDomainSurfaceVerification{@org.junit.jupiter.api.Test
    @org.junit.jupiter.api.Tag("domain")
        void verifiesCanonicalContract(){Set<String> n=Arrays.stream(Subprofession.values()).map(Enum::name).collect(java.util.stream.Collectors.toSet());for(String x:List.of("DEPENDENT_CHILD","UNPLACED_ADOLESCENT","SPECIALIZED_PRODUCER","AGRICULTURAL_LABORER","LIVESTOCK_CARETAKER"))org.junit.jupiter.api.Assertions.assertTrue(!n.contains(x),"Obsoleta: "+x);org.junit.jupiter.api.Assertions.assertTrue(!DayLaborerCanonicalProfiles.isDeprecated(Subprofession.FARMER,CharacterClass.INDOMITO),"Farmer absorbs Indomito");org.junit.jupiter.api.Assertions.assertTrue(!DayLaborerCanonicalProfiles.isDeprecated(Subprofession.LIVESTOCK_KEEPER,CharacterClass.APODERADO),"Livestock absorbs Apoderado");org.junit.jupiter.api.Assertions.assertTrue(!DayLaborerCanonicalProfiles.isDeprecated(Subprofession.LIVESTOCK_KEEPER,CharacterClass.HERALDO),"Livestock absorbs Heraldo");var ast=new AstrolabeItem();org.junit.jupiter.api.Assertions.assertTrue(ast instanceof AccessoryItem,"Astrolabio accessory");org.junit.jupiter.api.Assertions.assertTrue(!MiscellaneousEconomicCatalog.all().containsKey("Astrolabio"),"Astrolabio not misc");org.junit.jupiter.api.Assertions.assertTrue(AccessoryEconomicCatalog.all().containsKey("Astrolabio"),"Astrolabio priced as accessory");var c=CharacterMasteryCollection.forClass(CharacterClass.LUCHADOR);var p=new MasteryProgressState();for(String t:MasteryProgressionPolicy.REQUIRED_FEARE_TROPHIES)p.addFeareTrophy(t);var pol=new MasteryProgressionPolicy();var sh=CharacterSheet.of(1,1,1,1,1,12,1,12,1);pol.evaluate(c,sh,p);org.junit.jupiter.api.Assertions.assertTrue(c.knowledgeState(MasteryId.EMPATIA_ANIMAL)==MasteryKnowledgeState.UNKNOWN,"pet gate");p.registerCharismaFeraPet("perro");pol.evaluate(c,sh,p);org.junit.jupiter.api.Assertions.assertTrue(c.knowledgeState(MasteryId.EMPATIA_ANIMAL)==MasteryKnowledgeState.UNLOCKED,"one charisma pet enough");}}
